<script setup>
import {ref,computed,watch} from 'vue'
import {workbenchRequest} from '../lib/backends'
const props=defineProps({settings:Object,members:Array,conversationId:String,modelValue:Object,refreshToken:Number})
const emit=defineEmits(['update:modelValue'])
const data=ref(null),error=ref(''),loading=ref(false)
const plan=computed(()=>props.modelValue||{})
const conflict=computed(()=>data.value&&plan.value.kind&&(plan.value.expected_result_revision!==data.value.result_revision||plan.value.expected_plan_revision!==(data.value.closure_plan?.revision||0)))
function update(fields){emit('update:modelValue',{...plan.value,...fields})}
function rebase(){update({expected_result_revision:data.value.result_revision,expected_plan_revision:data.value.closure_plan?.revision||0})}
function choose(kind){update({kind,expected_result_revision:data.value.result_revision,expected_plan_revision:data.value.closure_plan?.revision||0,owner:plan.value.owner||props.settings.userId,note:plan.value.note||'',next_action:plan.value.next_action||'',due_at:plan.value.due_at||null})}
async function load(){loading.value=true;error.value='';data.value=null;try{data.value=await workbenchRequest(props.settings,'/conversations/'+props.conversationId+'/followup?user_id='+encodeURIComponent(props.settings.userId));}catch(e){error.value=e.message}finally{loading.value=false}}
watch(()=>[props.conversationId,props.settings.userId,props.settings.workspaceId,props.refreshToken],load,{immediate:true})
const dateValue=computed(()=>plan.value.due_at?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(plan.value.due_at)).replace(' ','T'):'')
</script>
<template><fieldset class="closure-plan" :aria-busy="loading"><legend>客户结果与后续安排</legend><p class="source-note">内部结案不会自动记作客户确认。历史样本也请说明是否需要回访。</p><p v-if="loading">正在核对客户结果…</p><p v-if="error" role="alert">{{error}} <button type="button" @click="load">重新读取</button></p><template v-if="data"><p v-if="data.customer_confirmation_required" class="source-note">事项已重新打开，需登记本轮客户确认；上一轮确认不能用于本次结案。</p><p v-if="data.closure_plan" class="source-note">上次安排：{{data.closure_plan.kind==='followup'?'仍需跟进':data.closure_plan.kind==='no_followup'?'无需回访':'客户已确认'}} · {{data.closure_plan.note}}</p><label>结案后的安排<select aria-label="结案后的安排" :value="plan.kind||''" required @change="choose($event.target.value)"><option value="" disabled>请选择</option><option value="confirmed" :disabled="data.customer_confirmation_required||data.customer_result?.status!=='confirmed'">客户已确认解决（需已有实际反馈）</option><option value="followup">内部结案，仍需跟进</option><option value="no_followup">无需回访，记录原因</option></select></label><template v-if="plan.kind==='followup'"><label>后续跟进负责人<select aria-label="后续跟进负责人" :value="plan.owner" required @change="update({owner:$event.target.value})"><option v-for="m in members" :value="m.id" :key="m.id">{{m.id}}</option></select></label><label>后续下一步<textarea aria-label="后续下一步" :value="plan.next_action" required maxlength="1000" rows="2" @input="update({next_action:$event.target.value})"/></label><label>后续跟进期限（上海）<input aria-label="后续跟进期限" type="datetime-local" :value="dateValue" required @input="update({due_at:$event.target.value?new Date($event.target.value+':00+08:00').toISOString():null})"/></label></template><label v-if="plan.kind&&plan.kind!=='confirmed'">{{plan.kind==='no_followup'?'无需回访原因':'内部结案与后续安排说明'}}<textarea aria-label="结案安排说明" :value="plan.note" required maxlength="2000" rows="2" @input="update({note:$event.target.value})"/></label><p v-if="conflict" role="alert">客户记录或安排已变化，你填写的内容已保留。<button type="button" @click="rebase">已核对最新记录，保留内容继续</button></p></template></fieldset></template>
